// Derived from the user-supplied Meshy moon-cradle. See provenance.json.
let data;
const packed='';
export function modelGeometryData(){
 if(!data){const s=atob(packed),bytes=new Uint8Array(s.length);for(let i=0;i<s.length;i++)bytes[i]=s.charCodeAt(i);const b=bytes.buffer;data={
  positions:new Float32Array(b,0,86865),
  normals:new Float32Array(b,347460,86865),
  uvs:new Float32Array(b,694920,57910),
  indices:new Uint16Array(b,926560,107994),
 };}
 return data;
}
